// pkg/boundary/sensors/passive_rf.go - Passive RF Sensor
//
// Implementation of SensorObserver for passive RF monitoring.
// Passive RF detects emissions from spacecraft (communications, radar)
// without transmitting, providing stealth capability.

package sensors

import (
	"fmt"
	"math"

	"ssis/pkg/config"
	"ssis/pkg/gen/axiom_zero/Boundary" // Generated by flatc
	"ssis/pkg/physics"

	zmq "github.com/pebbe/zmq4"
)

// PassiveRF implements SensorObserver for passive RF monitoring
type PassiveRF struct {
	config     config.SensorConfig
	subscriber *zmq.Socket
	latestObs  Observation
	latestCov  [36]float64
	deviceID   uint32
	sampleRate float64
	frequency  float64 // RF frequency [Hz]
}

// NewPassiveRF creates a new passive RF sensor instance
func NewPassiveRF(config config.SensorConfig) (*PassiveRF, error) {
	subscriber, err := zmq.NewSocket(zmq.SUB)
	if err != nil {
		return nil, fmt.Errorf("failed to create SUB socket: %w", err)
	}

	err = subscriber.Connect(config.Endpoint)
	if err != nil {
		subscriber.Close()
		return nil, fmt.Errorf("failed to connect to %s: %w", config.Endpoint, err)
	}

	err = subscriber.SetSubscribe("")
	if err != nil {
		subscriber.Close()
		return nil, fmt.Errorf("failed to subscribe: %w", err)
	}

	// Passive RF monitors various frequencies
	frequency := 2.4e9 // 2.4 GHz (common S-band)

	return &PassiveRF{
		config:     config,
		subscriber: subscriber,
		deviceID:   3,    // Passive RF sensor ID
		sampleRate: 25.0, // 25Hz nominal rate (slower than active radar)
		frequency:  frequency,
		latestCov:  constructRFCovariance(),
	}, nil
}

// GetObservation returns the latest observation from passive RF
func (p *PassiveRF) GetObservation() (Observation, error) {
	msg, err := p.subscriber.RecvBytes(0)
	if err != nil {
		return p.latestObs, nil
	}

	packet := Boundary.GetRootAsTelemetryPacket(msg, 0)

	obs := Observation{
		TimestampNs: packet.TimestampNs(),
		Wavelength:  3.0e8 / p.frequency, // RF wavelength
		DeviceID:    p.deviceID,
		Quality:     0.75, // Lower quality (passive detection)
		Covariance:  p.latestCov,
	}

	az := packet.AzimuthMeasured()
	el := packet.ElevationMeasured()

	// Passive RF has lower angular resolution
	obs.Position = physics.Vector3{
		math.Cos(el) * math.Cos(az),
		math.Cos(el) * math.Sin(az),
		math.Sin(el),
	}

	obs.Velocity = physics.Vector3{0, 0, 0}

	p.latestObs = obs
	return obs, nil
}

// GetCovariance returns the passive RF measurement uncertainty
func (p *PassiveRF) GetCovariance() [36]float64 {
	return p.latestCov
}

// GetWavelength returns the RF wavelength
func (p *PassiveRF) GetWavelength() float64 {
	return 3.0e8 / p.frequency
}

// GetDeviceID returns the passive RF sensor ID
func (p *PassiveRF) GetDeviceID() uint32 {
	return p.deviceID
}

// GetSampleRate returns the passive RF sample rate
func (p *PassiveRF) GetSampleRate() float64 {
	return p.sampleRate
}

// Close shuts down the ZMQ connection
func (p *PassiveRF) Close() error {
	if p.subscriber != nil {
		return p.subscriber.Close()
	}
	return nil
}

// constructRFCovariance builds default passive RF covariance
// Passive RF has the lowest angular resolution
func constructRFCovariance() [36]float64 {
	var cov [36]float64

	// Position uncertainty (passive RF has ~50x worse than optical)
	posSigma := 1e-3 // ~0.001 rad

	// Velocity uncertainty (high due to Doppler ambiguity)
	velSigma := 5e-4

	cov[0] = posSigma * posSigma
	cov[7] = posSigma * posSigma
	cov[14] = posSigma * posSigma
	cov[21] = velSigma * velSigma
	cov[28] = velSigma * velSigma
	cov[35] = velSigma * velSigma

	return cov
}
